// Attach to Android, then run with playwright-cli run-code --filename this file.
async page => {
    // A 4096-element ReLU graph, generated by reluModel([1, 4096]).
    const model = "";
    await page.evaluate(async model => {
        let resident, modelId;
        const send = async request => {
            const id = crypto.randomUUID();
            await window.Capacitor.nativePromise('RamGpu','submit',{id,payload:JSON.stringify(request)});
            const result = await fetch('/__rank_ml_result?id='+id).then(r=>r.json());
            if(result.error) throw Error(result.error);
            return result;
        };
        const invoke = async (model,input) => {
            const cached = resident === model;
            if(!cached) { modelId=(await send({action:'load',model})).modelId; resident=model; }
            return {...await send({action:'invoke',modelId,input}),cached};
        };
        const input = Array.from({ length: 4096 }, (_, i) => Math.fround((i - 2048) / 7));
        modelId = (await send({action:'load',model})).modelId;
        const id = crypto.randomUUID();
        // Exercise either arrival order: the waiter can precede the native call.
        const pending = fetch('/__rank_ml_result?id=' + id).then(response => response.json());
        await window.Capacitor.nativePromise('RamGpu', 'submit', { id, payload: JSON.stringify({ action:'invoke', modelId, input }) });
        const result = await pending;
        if (result.error) throw Error(result.error);
        if (result.output.length !== input.length || result.output.some((value, i) => value !== Math.max(0, input[i])))
            throw Error('Large RAM request lost or changed tensor values');
    }, model);
}
